import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.ClaimController;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.session.CurrentUser;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.settings.ViewerAllowed;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class PlanController {

    /** A plan as the screen shows it: its amount with two decimals, its dates, its interval in days
     *  or its day of the month (the other null), how many claims it has made so far, the day it was
     *  paused on (null while it runs), its past pauses and its amount changes, oldest first. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, long generated, LocalDate pausedOn, List<PauseView> pauses, List<ChangeView> changes) {
        static PlanView of(Plan p, Map<Long, Long> made) {
            return new PlanView(p.getId(), p.getPersonId(), p.getAmount().setScale(2).toPlainString(), p.getStart(),
                    p.getEvery(), p.getDay(), p.getEnd(), made.getOrDefault(p.getId(), 0L), p.getPausedOn(),
                    p.getPauses().stream().map(x -> new PauseView(x.from(), x.to())).toList(),
                    p.getChanges().stream().map(c -> new ChangeView(c.on(), c.amount().setScale(2).toPlainString())).toList());
        }
    }

    /** A past pause: from the day the plan was paused (inclusive) to the day it was resumed (exclusive). */
    public record PauseView(LocalDate from, LocalDate to) {
    }

    /** An amount change: the sheet's today it was made on and the new amount with two decimals. */
    public record ChangeView(LocalDate on, String amount) {
    }

    /** A plan's new amount: one the claim form takes for a new claim (0.00 or more, up to two decimals). */
    public record AmountForm(@NotNull @Pattern(regexp = "\\d{1,13}(\\.\\d{1,2})?") String amount) {
    }

    /** A plan as the form submits it: an amount the claim form takes for a new claim (0.00 or
     *  more, up to two decimals), a start (null: the sheet's today), either an interval of whole
     *  days (at least 1) or a day of the month (1 to 31), and an end. */
    public record PlanForm(
            @NotNull @Pattern(regexp = "\\d{1,13}(\\.\\d{1,2})?") String amount,
            LocalDate start,
            @Min(1) Integer every,
            @Min(1) @Max(31) Integer day,
            @NotNull LocalDate end) {
    }

    /** A generate's result: the claims made, in the order they were made, and the sheet's plans now. */
    public record GenerateView(List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;
    private final ClaimController claims;
    private final SettingsService settings;
    private final SheetService sheets;

    public PlanController(PlanService service, ClaimController claims, SettingsService settings, SheetService sheets) {
        this.service = service;
        this.claims = claims;
        this.settings = settings;
        this.sheets = sheets;
    }

    @GetMapping("/plans")
    public List<PlanView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        Map<Long, Long> made = service.madeCounts(sheetId);
        return service.list(sheetId).stream().map(p -> PlanView.of(p, made)).toList();
    }

    @PostMapping("/people/{personId}/plans")
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PlanForm body) {
        Plan plan = service.add(sheetId, user.trim(), personId, new BigDecimal(body.amount()), body.start(), body.every(),
                body.day(), body.end());
        return PlanView.of(plan, Map.of());
    }

    @PostMapping("/plans/{planId}/pause")
    public PlanView pause(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long planId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return PlanView.of(service.setPaused(sheetId, user.trim(), planId, true), service.madeCounts(sheetId));
    }

    @PostMapping("/plans/{planId}/resume")
    public PlanView resume(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long planId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return PlanView.of(service.setPaused(sheetId, user.trim(), planId, false), service.madeCounts(sheetId));
    }

    @PostMapping("/plans/{planId}/amount")
    public PlanView changeAmount(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long planId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody AmountForm body) {
        return PlanView.of(service.changeAmount(sheetId, user.trim(), planId, new BigDecimal(body.amount())),
                service.madeCounts(sheetId));
    }

    /** Generate the plans' claims; resolves to the claims made and the sheet's plans with their
     *  counts. Each claim is refused for a viewer and on an archived sheet, so it makes none. */
    @PostMapping("/plans/generate")
    @ViewerAllowed
    public GenerateView generate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        if (settings.isViewer(sheetId, user.trim()) || sheets.archived(sheetId)) {
            return new GenerateView(List.of(), list(sheetId, user));
        }
        List<ClaimView> made = service.generate(sheetId, user.trim()).stream().map(claims::view).toList();
        return new GenerateView(made, list(sheetId, user));
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Embeddable;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: a DRAFT claim of its amount for each plan date, up to its end. The plan dates
 *  are its start and then every so many days; or, for a monthly plan, its day of the month in every
 *  month from the start's month (a day beyond the month's length falling on its last day), leaving
 *  out those before the start. A date on or after the day the plan was paused and before the day it
 *  was resumed is skipped, not postponed; while it is paused, every date from the day it was. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private long personId;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    @Column(name = "every_days")
    private Integer every;

    @Column(name = "month_day")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    /** The sheet's today the plan was paused on; null while it runs. */
    @Column(name = "paused_on")
    private LocalDate pausedOn;

    /** The plan's past pauses, in the order they were resumed. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "position")
    private List<Pause> pauses = new ArrayList<>();

    /** The plan's amount changes, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "position")
    private List<Change> changes = new ArrayList<>();

    /** A change of the plan's amount: the sheet's today it was made on and the new amount. */
    @Embeddable
    public record Change(@Column(name = "on_date", nullable = false) LocalDate on,
            @Column(name = "amount", nullable = false, precision = 15, scale = 2) BigDecimal amount) {
    }

    /** A past pause: from the day the plan was paused (inclusive) to the day it was resumed (exclusive). */
    @Embeddable
    public record Pause(@Column(name = "from_date", nullable = false) LocalDate from,
            @Column(name = "to_date", nullable = false) LocalDate to) {
        /** Whether a plan date falls within it: on or after the from and before the to. */
        public boolean covers(LocalDate date) {
            return !date.isBefore(from) && date.isBefore(to);
        }
    }

    protected Plan() {
    }

    /** A plan of either an interval in days or a day of the month; the other is null. */
    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    /** The interval in days; null for a monthly plan. */
    public Integer getEvery() {
        return every;
    }

    /** The day of the month of a monthly plan; null for a plan of an interval in days. */
    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    public boolean isPaused() {
        return pausedOn != null;
    }

    /** The sheet's today the plan was paused on; null while it runs. */
    public LocalDate getPausedOn() {
        return pausedOn;
    }

    public List<Pause> getPauses() {
        return List.copyOf(pauses);
    }

    public List<Change> getChanges() {
        return List.copyOf(changes);
    }

    /** Change the plan's amount on a day: the claims it makes from then on are of the new amount. */
    public void changeAmount(LocalDate on, BigDecimal to) {
        amount = to;
        changes.add(new Change(on, to));
    }

    /** Pause the plan on a day: its dates from that day on are skipped until it is resumed. */
    public void pause(LocalDate on) {
        pausedOn = on;
    }

    /** Resume the plan on a day: its pause is kept as a past one, to that day. */
    public void resume(LocalDate on) {
        pauses.add(new Pause(pausedOn, on));
        pausedOn = null;
    }

    /** Whether the plan skips a date: one of its pauses covers it. */
    public boolean skips(LocalDate date) {
        return (pausedOn != null && !date.isBefore(pausedOn)) || pauses.stream().anyMatch(p -> p.covers(date));
    }

    /** The plan's dates up to its end and the date given that it does not skip, in order. */
    public List<LocalDate> datesUpTo(LocalDate until) {
        return allDatesUpTo(until).stream().filter(d -> !skips(d)).toList();
    }

    private List<LocalDate> allDatesUpTo(LocalDate until) {
        LocalDate last = end.isBefore(until) ? end : until;
        List<LocalDate> out = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last)) {
                    out.add(d);
                }
            }
            return out;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            out.add(d);
        }
        return out;
    }
}
