export class PersonPlans {
  readonly personId = input.required<number>();
  readonly personName = input.required<string>();

  protected readonly session = inject(Session);
  private readonly api = inject(PlansApi);

  protected readonly plans = computed(() => this.session.plans().filter((p) => p.personId === this.personId()));
  protected readonly error = signal<string | null>(null);
  /** Each plan's refused action, by plan id; removed when the next action on it is taken. */
  protected readonly rowErrors = signal<Record<number, string>>({});
  /** Each plan's new-amount entry, by plan id. */
  protected readonly amounts = signal<Record<number, string>>({});
  private submitting = false;

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    start: new FormControl('', { nonNullable: true }),
    every: new FormControl('', { nonNullable: true }),
    day: new FormControl('', { nonNullable: true }),
    end: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.error.set(null);
        this.rowErrors.set({});
        this.amounts.set({});
        this.form.reset({ amount: '', start: '', every: '', day: '', end: '' }, { emitEvent: false });
      });
    });
  }

  /** The plan's next five dates after the sheet's today, comma and space separated. */
  protected next(plan: Plan): string {
    const today = this.session.today();
    return today === null ? '' : nextDates(plan, today).join(', ');
  }

  /** Pause the plan (or, with `on` false, resume it) on the sheet's today. */
  protected async setPaused(plan: Plan, on: boolean): Promise<void> {
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    this.setRowError(plan.id, null);
    try {
      const saved = await this.api.setPaused(sheetId, plan.id, on);
      if (this.session.sheetId() === sheetId) {
        this.session.plans.update((ps) => ps.map((p) => (p.id === saved.id ? saved : p)));
      }
    } catch (e) {
      if (this.session.sheetId() === sheetId) this.setRowError(plan.id, pauseError(e));
    }
  }

  protected setAmount(planId: number, value: string): void {
    this.amounts.update((all) => ({ ...all, [planId]: value }));
    this.setRowError(planId, null);
  }

  /** Change the plan's amount to the one entered, on the sheet's today. */
  protected async changeAmount(plan: Plan): Promise<void> {
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    this.setRowError(plan.id, null);
    const amount = (this.amounts()[plan.id] ?? '').trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.setRowError(plan.id, 'Enter an amount of 0.00 or more with up to two decimals.');
      return;
    }
    try {
      const saved = await this.api.changeAmount(sheetId, plan.id, amount);
      if (this.session.sheetId() === sheetId) {
        this.session.plans.update((ps) => ps.map((p) => (p.id === saved.id ? saved : p)));
        this.amounts.update((all) => ({ ...all, [plan.id]: '' }));
      }
    } catch (e) {
      if (this.session.sheetId() === sheetId) this.setRowError(plan.id, amountError(e));
    }
  }

  private setRowError(planId: number, err: string | null): void {
    this.rowErrors.update((all) => {
      const next = { ...all };
      if (err === null) delete next[planId];
      else next[planId] = err;
      return next;
    });
  }

  protected fieldId(name: string): string {
    return `plan-form-${name}-${this.personId()}`;
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    const start = value.start.trim();
    const every = value.every.trim();
    const day = value.day.trim();
    const end = value.end.trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.error.set('Enter an amount of 0.00 or more with up to two decimals.');
      return;
    }
    if ((every === '') === (day === '')) {
      this.error.set('Repeat either every so many days or monthly on a day of the month.');
      return;
    }
    if (every !== '' && (!/^\d{1,9}$/.test(every) || Number(every) < 1)) {
      this.error.set('Repeat every whole number of days, 1 or more.');
      return;
    }
    if (day !== '' && (!/^\d{1,2}$/.test(day) || Number(day) < 1 || Number(day) > 31)) {
      this.error.set('Repeat monthly on a day of the month from 1 to 31.');
      return;
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(end)) {
      this.error.set('Enter an end date.');
      return;
    }
    const from = start === '' ? this.session.today() : start;
    if (from !== null && end < from) {
      this.error.set('The end cannot be before the start.');
      return;
    }
    this.submitting = true;
    try {
      const plan = await this.api.add(sheetId, this.personId(), { amount, start: start === '' ? null : start, every: every === '' ? null : Number(every),
        day: day === '' ? null : Number(day), end });
      if (this.session.sheetId() === sheetId) {
        this.session.plans.update((ps) => [...ps.filter((p) => p.id !== plan.id), plan].sort((a, b) => a.id - b.id));
      }
      this.form.reset({ amount: '', start: '', every: '', day: '', end: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(planError(e));
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import { plusDays, type Claim } from '../claims/claims-api';

/** A person's plan: a DRAFT claim of its amount (two decimals) for each plan date, its start and
 *  then every so many days, or its day of the month in every month from the start's (the other
 *  null), up to its end; with how many claims it has made so far. */
export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
  /** The sheet's today the plan was paused on; null while it runs. */
  pausedOn: string | null;
  /** Its past pauses: from the day it was paused (inclusive) to the day it was resumed (exclusive). */
  pauses: { from: string; to: string }[];
  /** Its amount changes, oldest first: the sheet's today each was made on and the new amount. */
  changes: { on: string; amount: string }[];
}

/** A plan as the form submits it: a blank start takes the sheet's today; one of every and day. */
export interface PlanForm {
  amount: string;
  start: string | null;
  every: number | null;
  day: number | null;
  end: string;
}

/** A generate's result: the claims made, in the order they were made, and the sheet's plans now. */
export interface Generated {
  claims: Claim[];
  plans: Plan[];
}

@Injectable({ providedIn: 'root' })
export class PlansApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's plans, in the order they were added. */
  list(sheetId: string): Promise<Plan[]> {
    return firstValueFrom(this.http.get<Plan[]>(`${this.url(sheetId)}/plans`, { headers: this.headers() }));
  }

  add(sheetId: string, personId: number, form: PlanForm): Promise<Plan> {
    return firstValueFrom(this.http.post<Plan>(`${this.url(sheetId)}/people/${personId}/plans`, form, { headers: this.headers() }));
  }

  /** Pause the plan (or, with `on` false, resume it) on the sheet's today. */
  setPaused(sheetId: string, planId: number, on: boolean): Promise<Plan> {
    return firstValueFrom(this.http.post<Plan>(`${this.url(sheetId)}/plans/${planId}/${on ? 'pause' : 'resume'}`, null, { headers: this.headers() }));
  }

  /** Change the plan's amount on the sheet's today; the claims it makes from then on take it. */
  changeAmount(sheetId: string, planId: number, amount: string): Promise<Plan> {
    return firstValueFrom(this.http.post<Plan>(`${this.url(sheetId)}/plans/${planId}/amount`, { amount }, { headers: this.headers() }));
  }

  /** Make the claims every plan on the sheet is due by the sheet's today. */
  generate(sheetId: string): Promise<Generated> {
    return firstValueFrom(this.http.post<Generated>(`${this.url(sheetId)}/plans/generate`, null, { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function planError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) {
    return 'Enter an amount of 0.00 or more with up to two decimals, a whole number of days of 1 or more or a day of the month of 1 to 31, and an end date.';
  }
  if (e instanceof HttpErrorResponse && e.status === 422) {
    return 'Give an end on or after the start, and repeat either every 1 day or more or monthly on a day of 1 to 31.';
  }
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on the sheet.';
  return otherError(e);
}

export function pauseError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only a running plan can be paused, and only a paused one resumed.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That plan is no longer on the sheet.';
  return otherError(e);
}

export function amountError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter an amount of 0.00 or more with up to two decimals.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That plan is no longer on the sheet.';
  return otherError(e);
}

/** Whether the plan skips a date: it falls on or after the day a pause began and before the day
 *  it was resumed, or on or after the day of the pause still in force. */
export function skips(plan: Plan, date: string): boolean {
  if (plan.pausedOn !== null && date >= plan.pausedOn) return true;
  return plan.pauses.some((p) => date >= p.from && date < p.to);
}

/** The plan's first `count` dates after the date given and on or before its end, in order: its
 *  start and then every so many days; or its day of the month (on the month's last day when the
 *  month is shorter) in every month from the start's, leaving out those before the start and
 *  those it skips for a pause. */
export function nextDates(plan: Plan, after: string, count = 5): string[] {
  const out: string[] = [];
  if (plan.day !== null) {
    let year = Number(plan.start.slice(0, 4));
    let month = Number(plan.start.slice(5, 7));
    while (out.length < count) {
      const first = `${year}-${pad(month)}-01`;
      if (first > plan.end) break;
      const length = new Date(Date.UTC(year, month, 0)).getUTCDate();
      const d = `${year}-${pad(month)}-${pad(Math.min(plan.day, length))}`;
      if (d >= plan.start && d > after && d <= plan.end && !skips(plan, d)) out.push(d);
      month += 1;
      if (month > 12) {
        month = 1;
        year += 1;
      }
    }
    return out;
  }
  const every = plan.every ?? 1;
  let d = plan.start;
  if (d <= after) {
    const gap = Math.round((Date.parse(after) - Date.parse(d)) / 86_400_000);
    d = plusDays(d, (Math.floor(gap / every) + 1) * every);
  }
  for (; out.length < count && d <= plan.end; d = plusDays(d, every)) {
    if (!skips(plan, d)) out.push(d);
  }
  return out;
}

function pad(n: number): string {
  return String(n).padStart(2, '0');
}
-- A plan's amount can be changed. Each change is kept, oldest first, with the sheet's today it was
-- made on and the new amount; the plan's amount is the latest. A claim already made keeps its own.
CREATE TABLE plan_change (
    plan_id    BIGINT         NOT NULL REFERENCES plan (id),
    position   INT            NOT NULL,
    on_date    DATE           NOT NULL,
    amount     DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (plan_id, position)
);
